/// <summary>
/// Class to contain a collection of either text elements or image elements
/// </summary>
[TFMListElementAttribute('elements')]
class TFMListElements extends TFMListBase implements TFMListElementHierarchyInterface
{
}

Method.Source:
	public static TFMListElements Construct()
    {
        return new TFMListElements();
    }

    public Set getCustomComponents()
    {        
        Set						retSet = new Set(Types::Class);
        MapEnumerator			mEnum;
        Object					element;

        TFMListCustomComponent	customComponent;

        if (!baseChildren)
        {
            return retSet;
        }
        mEnum = baseChildren.getEnumerator();
        while (mEnum.moveNext())
        {
            element = mEnum.currentValue();
			if (new SysDictClass(classIdGet(element)).extend() == classNum(TFMListCustomComponent))
            {
                customComponent = element;
                retSet.add(customComponent);
            }
        }
        return retSet;
    }
